mapper.select:
SELECT COMPANY_CODE AS companyCode, SKU AS sku, SKU_NAME AS skuName, SKU_TYPE AS skuType, UNIT AS unit, SPEC AS spec, REMARK AS remark, USE_YN AS useYn, TAX_YN AS taxYn, CREATED_BY AS createdBy, CREATE_DATE AS createDate, UPDATED_BY AS updatedBy, UPDATE_DATE AS updateDate FROM TB_SKU_MASTER WHERE COMPANY_CODE = #{companyCode}
AND SKU LIKE '%' || #{sku} || '%'
AND SKU_NAME LIKE '%' || #{skuName} || '%'
AND SKU_TYPE = #{skuType}
ORDER BY TO_NUMBER(SUBSTR(SKU, 2)) DESC

SELECT COUNT(1)
FROM TB_SKU_MASTER
WHERE COMPANY_CODE = #{companyCode}
  AND SKU = #{sku}
